import{_ as s,a0 as u,w as r,s as i,ao as d,I as o,x as t,a1 as l,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"為何我們需要一個開放模型來設計評估公共政策 | LCTT x X-CMD","titleTemplate":false,"description":"為何我們需要一個開放模型來設計評估公共政策 | LCTT (201705) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為何我們需要一個開放模型來設計評估公共政策 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為何我們需要一個開放模型來設計評估公共政策 | LCTT (201705) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201705/20170110 Why we need an open model to design and evaluate public policy","title":"為何我們需要一個開放模型來設計評估公共政策","tag":"201705","desc":""},"relativePath":"201705/20170110 Why we need an open model to design and evaluate public policy.md","filePath":"[post].md"}'),a={name:"201705/20170110 Why we need an open model to design and evaluate public policy.md"};function m(f,e,g,y,b,T){const p=u("Link");return r(),i("div",null,[e[18]||(e[18]=d('<h1 id="為何我們需要一個開放模型來設計評估公共政策" tabindex="-1">為何我們需要一個開放模型來設計評估公共政策 <a class="header-anchor" href="#為何我們需要一個開放模型來設計評估公共政策" aria-label="Permalink to “為何我們需要一個開放模型來設計評估公共政策”">​</a></h1><blockquote><p>想像一個 app 可以讓市民來試車提出的政策。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/government/GOV_citizen_participation.jpg?itok=eeLWQgev" alt="Why we need an open model to design and evaluate public policy" title="Why we need an open model to design and evaluate public policy"></p><p>圖片提供：opensource.com</p><p>在政治選舉之前的幾個月中，公眾辯論會加劇，並且公民面臨大量的各種政策選擇的信息。在數據驅動的社會中，新的見解一直在為決策提供信息，對這些信息的深入瞭解從未如此重要，但公眾仍然沒有意識到為公共政策建模的全部潛力。</p><p>在“<ruby>開放政府<rt>open government</rt></ruby>”的概念不斷演變以跟上新技術進步的時代，政府的政策模型和分析可能是新一代的開放知識。</p><p>政府開源模型 （GOSM） 是指政府開發的模型，其目的是設計和評估政策，免費提供給所有人使用、分發、不受限制地修改。社區可以提高政策建模的質量、可靠性和準確性，創造有利於公眾的新的數據驅動程序。</p><p>今天的這一代人與技術相互作用，這儼然成為了它的第二種本質，自然而然地吸收了大量的信息。如果我們可以在使用 GOSM 在虛擬、沉浸式環境中與不同的公共政策進行互動那會如何？</p><p>想像一下如果有一個程序，允許公民試車提出的政策來確定他們想要生活的未來。他們會本能地學習關鍵的驅動因素和所需要的東西。不久之後，公眾將更深入地瞭解公共政策的影響，並更加精明地引導有爭議性的公眾辯論。</p><p>為什麼我們以前沒有更好的使用這些模型？原因在於公共政策建模的神秘面紗。</p><p>在一個如我們所生活的複雜的社會中，量化政策影響是一項艱鉅的任務，並被被描述為一種“美好藝術”。此外，大多數政府政策模型都是基於行政和其他私人持有的數據。然而，政策分析師為了指導政策設計而勇於追求，多次以大量武力而贏得政治鬥爭的勝利。</p><p>數字是很有説服力的。它們構建可信度，並常常被用作引入新政策的理由。公共政策模型的發展賦予政治家和官僚權力，這些政治家和官僚們可能不願意破壞現狀。給予這一點可能並不容易，但 GOSM 為前所未有的公共政策改革提供了機會。</p><p>GOSM 將所有人的競爭環境均衡化：政治家、媒體、遊説團體、利益相關者和公眾。通過向社區開放政策評估的大門, 政府可以在公共領域為創造、創新和效率引入新的和未發現的能力。但在公共政策設計中，利益相關者和政府之間戰略互動有哪些實際影響？</p><p>GOSM 是獨一無二的，因為它們主要是設計公共政策的工具，而不一定需要重新分配私人收益。利益相關者和遊説團體可能會將 GOSM 與其私人信息一起使用，以獲得對經濟參與者私人利益的政策環境運作的新見解。</p><p>GOSM 可以成為利益相關者在公共辯論中保持權力平衡的武器，併為戰略爭取最佳利益麼？</p><p>作為一個可變的公共資源，GOSM 在概念上由納税人資助，並屬於國家。私有實體在不向社會帶來利益的情況下從 GOSM 中獲得資源是合乎道德的嗎？與可能用於更有效的服務提供的那些程序不同，替代政策建議更有可能由諮詢機構使用，並有助於公眾辯論。</p><p>開源社區經常使用 “copyleft 許可證” 來確保代碼和在此許可證下的任何衍生作品對所有人都開放。當產品價值是代碼本身，這需要重新分配才能獲得最大利益，它需要重新分發來獲得最大的利益。但是，如果代碼或 GOSM 重新分發是主要產品附帶的，那它會是對現有政策環境的新戰略洞察麼？</p><p>在私人收集的數據變得越來越多的時候，GOSM 背後的真正價值可能是底層數據，它可以用來改進模型本身。最終，政府是唯一有權實施政策的消費者，利益相關者可以選擇在談判中分享修改後的 GOSM。</p><p>政府在公開發佈政策模型時面臨的巨大挑戰是提高透明度的同時保護隱私。理想情況下，發佈 GOSM 將需要以保護建模關鍵特徵的方式保護封閉的數據。</p><p>公開發布 GOSM 通過促進市民對民主的更多瞭解和參與，使公民獲得權力，從而改善政策成果和提高公眾滿意度。在開放的政府烏托邦中，開放的公共政策發展將是政府和社區之間的合作性努力，這裏知識、數據和分析可供大家免費使用。</p>',20)),o("p",null,[o("em",null,[e[2]||(e[2]=t("在霍巴特舉行的 linux.conf.au 2017（",-1)),l(p,{href:"https://twitter.com/search?q=%23lca2017&src=typd"},{default:n(()=>[...e[0]||(e[0]=[t("＃lca2017",-1)])]),_:1}),e[3]||(e[3]=t("）瞭解更多 Audrey Lobo-Pulo 的講話：",-1)),l(p,{href:"https://linux.conf.au/schedule/presentation/31/"},{default:n(()=>[...e[1]||(e[1]=[t("公開發布的政府模型",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))])]),e[19]||(e[19]=o("p",null,[o("em",null,"聲明：本文中提出的觀點屬於 Audrey Lobo-Pulo，不一定是澳大利亞政府的觀點。")],-1)),e[20]||(e[20]=o("hr",null,null,-1)),e[21]||(e[21]=o("p",null,"作者簡介：",-1)),e[22]||(e[22]=o("p",null,[o("img",{src:"https://opensource.com/sites/default/files/styles/profile_pictures/public/pictures/1-_mg_2552.jpg?itok=-RflZ4Wv",alt:""})],-1)),e[23]||(e[23]=o("p",null,"Audrey Lobo-Pulo - Audrey Lobo-Pulo 博士是 Phoensight 的聯合創始人，並且開放政府以及政府建模開源軟件的倡導者。一位物理學家，在加入澳大利亞公共服務部後，她轉而從事經濟政策建模工作。Audrey 參與了各種經濟政策選擇的建模，目前對政府開放數據和開放式政策建模感興趣。 Audrey 對政府的願景是將數據科學納入公共政策分析。",-1)),e[24]||(e[24]=o("hr",null,null,-1)),o("p",null,[e[6]||(e[6]=t("via: ",-1)),l(p,{href:"https://opensource.com/article/17/1/government-open-source-models"},{default:n(()=>[...e[5]||(e[5]=[t("https://opensource.com/article/17/1/government-open-source-models",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("作者：",-1)),l(p,{href:"https://opensource.com/users/audrey-lobo-pulo"},{default:n(()=>[...e[7]||(e[7]=[t("Audrey Lobo-Pulo",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),l(p,{href:"https://github.com/geekpi"},{default:n(()=>[...e[8]||(e[8]=[t("geekpi",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),l(p,{href:"https://github.com/wxy"},{default:n(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[15]||(e[15]=t("本文由 ",-1)),l(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創編譯，",-1)),l(p,{href:"https://linux.cn/"},{default:n(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const x=s(a,[["render",m]]);export{v as __pageData,x as default};
